/* ================= 全局容器 ================= */
.diary-card-widget {
  width: 100%; height: 100%;
  background-color: transparent !important; 
  padding: clamp(8px, 2.5vw, 12px); 
  box-sizing: border-box;
  font-family: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif; 
  position: relative;

  /* 建立全局自适应响应式变量 */
  --avatar-size: clamp(48px, 14vw, 65px);
  --gap-size: clamp(10px, 3vw, 16px);
  --inner-pad: clamp(6px, 2vw, 12px);
}

/* ================= 🌟 模式控制引擎 ================= */
.diary-card-widget .inner-card,
.diary-card-widget .avatar-frame,
.diary-card-widget .chat-bubble {
  background-color: var(--bg-card);
}

.diary-card-widget[data-bg-style="frosted"] .inner-card,
.diary-card-widget[data-bg-style="frosted"] .avatar-frame,
.diary-card-widget[data-bg-style="frosted"] .chat-bubble {
  background-color: color-mix(in srgb, var(--bg-card) 55%, transparent);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
}

.diary-card-widget[data-bg-style="dots"] .inner-card,
.diary-card-widget[data-bg-style="dots"] .avatar-frame,
.diary-card-widget[data-bg-style="dots"] .chat-bubble {
  background-color: var(--bg-card);
  background-image: radial-gradient(var(--theme-col) 1.5px, transparent 1.5px), radial-gradient(var(--theme-col) 1.5px, transparent 1.5px);
  background-size: 20px 20px; background-position: 0 0, 10px 10px;
  backdrop-filter: none; -webkit-backdrop-filter: none;
}

.diary-card-widget[data-bg-style="trans-dots"] .inner-card,
.diary-card-widget[data-bg-style="trans-dots"] .avatar-frame,
.diary-card-widget[data-bg-style="trans-dots"] .chat-bubble {
  background-color: color-mix(in srgb, var(--bg-card) 55%, transparent);
  background-image: radial-gradient(var(--theme-col) 1.5px, transparent 1.5px), radial-gradient(var(--theme-col) 1.5px, transparent 1.5px);
  background-size: 20px 20px; background-position: 0 0, 10px 10px;
  backdrop-filter: none; -webkit-backdrop-filter: none;
}


/* ================= 🚨 防剪裁安全区 (改用 Flex 弹性流布局) ================= */
.safe-area { 
  position: relative; width: 100%; height: 100%; z-index: 1; 
  /* 魔法代码：让内部元素变成从上到下的积木排列，绝不互相乱撞 */
  display: flex;
  flex-direction: column;
}

/* ================= 🚨 内部卡片 (取消绝对定位) ================= */
.inner-card {
  position: relative; 
  flex: 1; /* 自动撑满除了底部气泡外的所有剩余空间 */
  width: calc(100% - clamp(16px, 5vw, 24px)); /* 右侧留出圆圈的空间 */
  margin-top: clamp(2px, 1vw, 6px); /* 顶部留白 */

  border: 1.5px solid var(--border-col);
  border-radius: clamp(16px, 4vw, 20px);
  padding: clamp(10px, 3vw, 14px) clamp(12px, 3.5vw, 16px); 
  box-sizing: border-box;
  display: flex; flex-direction: column;
}

img { color: transparent; font-size: 0; }

/* ================= 左上角装饰药丸 ================= */
.decor-pills { 
  position: absolute; top: clamp(-10px, -3vw, -14px); left: clamp(16px, 5vw, 24px); 
  display: flex; gap: 6px; z-index: 10; 
}
.pill { width: clamp(12px, 3.5vw, 16px); height: clamp(24px, 7vw, 32px); background-color: var(--theme-col); border-radius: 99px; }

/* ================= 顶部信息区 ================= */
.card-header {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: clamp(6px, 2vw, 10px); 
  padding-left: calc(var(--inner-pad) + var(--avatar-size) + var(--gap-size)); 
}
.username-wrap { font-size: clamp(13px, 3.5vw, 16px); font-style: italic; font-weight: 600; color: var(--text-main); }
.date-display {
  font-size: clamp(13px, 3.5vw, 16px); font-weight: 600; color: var(--text-main);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; letter-spacing: 1px;
}

/* ================= 主体内容区 ================= */
.card-body {
  display: flex; gap: var(--gap-size); flex: 1; align-items: center; 
  padding-left: var(--inner-pad); box-sizing: border-box;
}

/* 左侧方形头像 */
.avatar-frame {
  width: var(--avatar-size); height: var(--avatar-size); flex-shrink: 0;
  border: 1.5px solid var(--theme-col); border-radius: clamp(10px, 3vw, 14px); 
  padding: clamp(2px, 0.8vw, 4px); box-sizing: border-box;
}
.avatar-inner {
  width: 100%; height: 100%; border-radius: 8px; overflow: hidden; background-color: rgba(0,0,0,0.03); 
}
.avatar-inner img { width: 100%; height: 100%; object-fit: cover; display: block; }

/* 右侧多行文案 */
.content-area {
  height: var(--avatar-size); flex: 1; display: flex; flex-direction: column; justify-content: space-between; 
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; box-sizing: border-box;
}
.text-line { 
  font-size: clamp(11px, 2.8vw, 14px); color: var(--text-sub); line-height: 1.1; 
  word-break: break-all; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* ================= 右下角悬浮圆图 ================= */
.circle-decor {
  position: absolute; right: 0; 
  /* 让圆圈悬浮在靠下的位置 */
  bottom: clamp(12px, 4vw, 24px);
  width: clamp(48px, 14vw, 65px); height: clamp(48px, 14vw, 65px);
  border-radius: 50%; border: 2px solid var(--theme-col); overflow: hidden;
  background-color: var(--theme-col); z-index: 20;
}
.circle-decor img { width: 100%; height: 100%; object-fit: cover; display: block; }

/* ================= 🚨 底部独立文案框 (取消绝对定位，物理隔离) ================= */
.chat-bubble-wrapper {
  position: relative; 
  align-self: flex-start; /* 靠左对齐 */

  /* 🌟 核心距离控制！这里的 margin-top 就是气泡距离主卡片的距离，它是被物理焊死的，数字多大间距就有多大 */
  margin-top: clamp(8px, 2.5vw, 12px); 

  margin-left: clamp(16px, 5vw, 24px); 
  margin-bottom: clamp(2px, 1vw, 6px); /* 距离最底部的保留空间 */
  z-index: 25;
}
.chat-bubble {
  display: inline-flex; align-items: center;
  border: 1.5px solid var(--border-col); border-radius: clamp(12px, 3.5vw, 16px); 
  padding: clamp(4px, 1.5vw, 6px) clamp(10px, 3vw, 14px); position: relative;
  font-size: clamp(11px, 3vw, 14px); color: var(--text-main);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
